// ListCrops handles list requests.
func (h *CropHandler) ListCrops(ctx context.Context, req *connect.Request[pb.ListCropsRequest]) (*connect.Response[pb.ListCropsResponse], error) {
	tenantID := req.Msg.GetTenantId()
	if tenantID == "" {
		tenantID = p9context.TenantID(ctx)
	}

	var category *string
	if req.Msg.GetCategory() != pb.CropCategory_CROP_CATEGORY_UNSPECIFIED {
		cat := string(mappers.CategoryFromProto(req.Msg.GetCategory()))
		category = &cat
	}
	var searchTerm *string
	if req.Msg.GetSearchTerm() != "" {
		s := req.Msg.GetSearchTerm()
		searchTerm = &s
	}

	entities, total, err := h.svc.ListCrops(ctx, tenantID, category, searchTerm, req.Msg.GetPageSize(), req.Msg.GetPageOffset())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.ListCropsResponse{
		Crops:      mappers.CropSliceToProto(entities),
		TotalCount: total,
	}), nil
}

// UpdateCrop handles update requests.
func (h *CropHandler) UpdateCrop(ctx context.Context, req *connect.Request[pb.UpdateCropRequest]) (*connect.Response[pb.UpdateCropResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	tenantID := req.Msg.GetTenantId()
	if tenantID == "" {
		tenantID = p9context.TenantID(ctx)
	}
	userID := p9context.UserID(ctx)

	entity := &cropmodels.Crop{
		TenantID:               tenantID,
		Name:                   req.Msg.GetName(),
		ScientificName:         req.Msg.GetScientificName(),
		Family:                 req.Msg.GetFamily(),
		Category:               mappers.CategoryFromProto(req.Msg.GetCategory()),
		Description:            req.Msg.GetDescription(),
		ImageURL:               req.Msg.GetImageUrl(),
		DiseaseSusceptibilities: req.Msg.GetDiseaseSusceptibilities(),
		CompanionPlants:        req.Msg.GetCompanionPlants(),
		RotationGroup:          req.Msg.GetRotationGroup(),
		Version:                req.Msg.GetVersion(),
	}
	entity.UUID = req.Msg.GetId()
	entity.UpdatedBy = &userID

	updated, err := h.svc.UpdateCrop(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.UpdateCropResponse{Crop: mappers.CropToProto(updated)}), nil
}

