// AddVariety handles add variety requests.
func (h *CropHandler) AddVariety(ctx context.Context, req *connect.Request[pb.AddVarietyRequest]) (*connect.Response[pb.AddVarietyResponse], error) {
	if req.Msg.GetCropId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "crop_id is required")
	}
	if req.Msg.GetName() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "name is required")
	}
	tenantID := req.Msg.GetTenantId()
	if tenantID == "" {
		tenantID = p9context.TenantID(ctx)
	}
	userID := p9context.UserID(ctx)

	// Resolve crop UUID to internal ID for the variety FK.
	crop, err := h.svc.GetCrop(ctx, req.Msg.GetCropId(), tenantID)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}

	variety := mappers.CropVarietyFromAddRequest(req.Msg, crop.ID, userID)
	variety.TenantID = tenantID

	created, err := h.svc.AddVariety(ctx, variety)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	proto := mappers.CropVarietyToProto(created)
	proto.CropId = req.Msg.GetCropId()
	return connect.NewResponse(&pb.AddVarietyResponse{Variety: proto}), nil
}

